    "highYield": [
      "Helicobacter pylori is a gram-negative, spiral-shaped bacterium implicated in chronic gastritis and peptic ulcer disease.",
      "Urease production by H. pylori neutralizes gastric acid, allowing survival in the acidic stomach environment.",
      "H. pylori infection is associated with gastric adenocarcinoma and MALT lymphoma.",
      "The urea breath test and stool antigen test are commonly used non-invasive diagnostic tests for H. pylori.",
      "First-line treatment includes a combination of a proton pump inhibitor (PPI), clarithromycin, and amoxicillin or metronidazole.",
      "Resistance to clarithromycin is a growing concern, necessitating alternative regimens in resistant cases."
    ],
    "mechanism": {
      "title": "Pathogenesis of H. pylori-induced gastric damage",
      "steps": [
        {
          "id": "s1",
          "label": "H. pylori colonizes gastric epithelium"
        },
        {
          "id": "s2",
          "label": "Urease activity increases local pH"
        },
        {
          "id": "s3",
          "label": "Inflammatory response damages epithelium"
        },
        {
          "id": "s4",
          "label": "Increased gastrin leads to acid hypersecretion"
        },
        {
          "id": "s5",
          "label": "Chronic inflammation progresses to atrophy/metaplasia"
        },
        {
          "id": "s6",
          "label": "Potential progression to dysplasia and malignancy"
        }
      ]
    },
    "examFindings": [
      {
        "sign": "Epigastric pain relieved by food or antacids",
        "mechanism": "Ulcer pain is relieved by buffering of acid",
        "significance": "key"
      },
      {
        "sign": "Positive urea breath test",
        "mechanism": "H. pylori urease activity hydrolyzes urea to CO2",
        "significance": "key"
      }
    ],
    "investigations": [
      {
        "clue": "Endoscopic biopsy with rapid urease test",
        "meaning": "Confirms H. pylori presence via urease activity"
      },
      {
        "clue": "Stool antigen test",
        "meaning": "Non-invasive test for active infection"
      }
    ],
    "treatment": [
      {
        "logic": "Triple therapy with PPI, clarithromycin, and amoxicillin",
        "detail": "First-line for H. pylori eradication"
      },
      {
        "logic": "Use of bismuth quadruple therapy",
        "detail": "Alternative in clarithromycin-resistant cases"
      }
    ],
    "mnemonics": [
      {
        "hook": "CAP for H. pylori",
        "expansion": [
          "Clarithromycin",
          "Amoxicillin",
          "PPI"
        ]
      }
    ],
    "traps": [
      {
        "questionCategory": "diagnosis",
        "wrongInstinct": "Serology for H. pylori antibodies",
        "rightAnswer": "Urea breath test",
        "why": "Serology does not distinguish active from past infection"
      }
    ],
    "quiz": [
      {
        "id": "q1",
        "stem": "A 45-year-old man presents with epigastric pain that improves with eating. A urea breath test is positive. What is the most appropriate treatment?",
        "options": [
          {
            "id": "a",
            "text": "PPI alone"
          },
          {
            "id": "b",
            "text": "Triple therapy with PPI, clarithromycin, and amoxicillin"
          },
          {
            "id": "c",
            "text": "Bismuth subsalicylate"
          },
          {
            "id": "d",
            "text": "H2 receptor antagonist"
          }
        ],
        "answerId": "b",
        "explanation": "Triple therapy is the standard treatment for H. pylori infection. PPI alone and H2 receptor antagonists do not eradicate the bacterium.",
        "tests": "treatment"
      }
    ]
